import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { excursions } from '../../Data/excursions';
import './CartPage.css';

const CartPage = () => {
  // MOCK — позже придёт с API
  const [cartItems, setCartItems] = useState(
    excursions.slice(0, 2).map(item => ({
      ...item,
      guests: 2
    }))
  );

  const [orderSuccess, setOrderSuccess] = useState(false);

  const totalPrice = cartItems.reduce(
    (sum, item) => sum + item.price * item.guests,
    0
  );

  const handleRemove = (id) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const handleCheckout = () => {
    setOrderSuccess(true);
    setCartItems([]);
  };

  return (
    <div className="cart-page">
      <div className="cart-container">
        <h1 className="cart-title">Корзина</h1>

        {orderSuccess ? (
          /* ✅ УСПЕШНЫЙ ЗАКАЗ */
          <div className="cart-success">
            <h2>Ваш заказ успешно оформлен!</h2>
            <p>Наш менеджер свяжется с вами в ближайшее время.</p>

            <Link to="/catalog" className="browse-button">
              Вернуться в каталог
            </Link>
          </div>
        ) : cartItems.length === 0 ? (
          /* EMPTY */
          <div className="cart-empty">
            <img
              src="/assets/icons/cart.svg"
              alt="Пустая корзина"
              className="empty-icon"
            />
            <h2>Корзина пуста</h2>
            <p>Добавьте экскурсии из каталога</p>
            <Link to="/catalog" className="browse-button">
              Перейти в каталог
            </Link>
          </div>
        ) : (
          <>
            {/* LIST */}
            <div className="cart-list">
              {cartItems.map(item => (
                <div key={item.id} className="cart-item">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="cart-item__image"
                  />

                  <div className="cart-item__info">
                    <h3>{item.title}</h3>
                    <p>{item.country}, {item.city}</p>

                    <div className="cart-item__controls">
                      <button
                        className="qty-btn"
                        disabled={item.guests <= 1}
                        onClick={() =>
                          setCartItems(prev =>
                            prev.map(el =>
                              el.id === item.id
                                ? { ...el, guests: el.guests - 1 }
                                : el
                            )
                          )
                        }
                      >
                        −
                      </button>

                      <span className="qty-value">{item.guests}</span>

                      <button
                        className="qty-btn"
                        onClick={() =>
                          setCartItems(prev =>
                            prev.map(el =>
                              el.id === item.id
                                ? { ...el, guests: el.guests + 1 }
                                : el
                            )
                          )
                        }
                      >
                        +
                      </button>
                    </div>

                    <button
                      className="cart-item__remove"
                      onClick={() => handleRemove(item.id)}
                    >
                      Удалить
                    </button>
                  </div>

                  <div className="cart-item__total">
                    {(item.price * item.guests).toLocaleString()} ₽
                  </div>
                </div>
              ))}
            </div>

            {/* SUMMARY */}
            <div className="cart-summary">
              <div className="cart-summary__total">
                Итого: <strong>{totalPrice.toLocaleString()} ₽</strong>
              </div>

              <button
                className="cart-checkout-btn"
                onClick={handleCheckout}
              >
                Оформить заказ
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default CartPage;
